package com.abhishek.hotelbooking.service.impl;
import com.abhishek.hotelbooking.dto.auth.*; import com.abhishek.hotelbooking.entity.User; import com.abhishek.hotelbooking.enums.Role; import com.abhishek.hotelbooking.exception.ConflictException; import com.abhishek.hotelbooking.repository.UserRepository; import com.abhishek.hotelbooking.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;} public AuthResponse register(RegisterRequest r){if(users.existsByEmail(r.email()))throw new ConflictException("Email already registered"); User u=users.save(User.builder().email(r.email()).password(encoder.encode(r.password())).fullName(r.fullName()).role(Role.USER).build()); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),"Bearer",u.getEmail(),u.getRole().name());} public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email()).orElseThrow(()->new RuntimeException("Invalid credentials")); if(!encoder.matches(r.password(),u.getPassword()))throw new RuntimeException("Invalid credentials"); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),"Bearer",u.getEmail(),u.getRole().name());} }